import * as THREE from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  texture,
  mul,
  add,
  position,
  normalWorld,
  float
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string, depthMapUrl:string, meshUrl?:string}} assets
 * @property {[number,number,number]} position
 * @property {[number,number,number]} rotation
 * @property {[number,number,number]} scale
 * @property {{name:string, trigger?:string, params:any}[]} cinematicPrimitives
 * @property {{event:string, effect:string}[]} interactions
 * @property {any} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {(url:string)=>Promise<THREE.Group>} glbLoader
 * @property {{[key:string]:(obj:THREE.Object3D, params:any)=>void}} primitives
 * @property {{emit?: (event:string)=>void}} [emit] // optional emitter helper
 */

/**
 * Creates a parallax‑plane quote panel node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -------------------------------------------------
  // Load textures (cached by ctx)
  // -------------------------------------------------
  const colorMap = ctx.textureLoader(config.assets.imageUrl);
  const depthMap = ctx.textureLoader(config.assets.depthMapUrl);

  // -------------------------------------------------
  // Geometry (tessellated plane)
  // -------------------------------------------------
  // Preserve aspect ratio of the source rect (512 x 320)
  const aspect = 512 / 320;
  const width = aspect; // height = 1 unit, width = aspect units
  const height = 1;
  const geometry = new THREE.PlaneGeometry(width, height, 64, 64);

  // -------------------------------------------------
  // Node‑based material with displacement
  // -------------------------------------------------
  const material = new MeshStandardNodeMaterial();

  // Base colour from image
  material.color = texture(colorMap);

  // Displacement from depth map (scalar tuned for subtle depth)
  const displacementScale = 0.2; // scene‑units, adjust as needed
  const depthNode = texture(depthMap);
  const dispNode = mul(depthNode.r, float(displacementScale));
  material.position = add(position, mul(normalWorld, dispNode));

  // Machined‑metal look
  material.metalness = 0.4;      // ≤ 0.55
  material.roughness = 0.6;      // ≥ 0.5
  material.clearcoat = 0.2;      // ≤ 0.25

  // -------------------------------------------------
  // Mesh assembly
  // -------------------------------------------------
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...config.position);
  mesh.rotation.set(...config.rotation);
  mesh.scale.set(...config.scale);

  // -------------------------------------------------
  // Apply cinematic primitives from config
  // -------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params ?? {});
      }
    }
  }

  // -------------------------------------------------
  // Interaction handling (hover rise‑in, click emit)
  // -------------------------------------------------
  const originalY = mesh.position.y;
  const riseAmount = 0.15; // scene units as spec'd
  const riseTimeline = gsap.timeline({ paused: true });
  riseTimeline.to(
    mesh.position,
    {
      y: originalY + riseAmount,
      duration: 0.7,
      ease: 'power3.out'
    },
    0
  );

  // Prepare userData.handlers container
  mesh.userData.handlers = {};

  // Hover interaction (rise‑in)
  mesh.userData.handlers.hover = () => {
    riseTimeline.play();
  };
  mesh.userData.handlers.unhover = () => {
    riseTimeline.reverse();
  };

  // Click interaction (emit event)
  mesh.userData.handlers.click = () => {
    if (ctx.emit && typeof ctx.emit === 'function') {
      ctx.emit('hub-home.select');
    }
  };

  // -------------------------------------------------
  // Cleanup routine
  // -------------------------------------------------
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // If texture loader provides a release/dispose method, invoke it.
    if (colorMap && typeof colorMap.dispose === 'function') colorMap.dispose();
    if (depthMap && typeof depthMap.dispose === 'function') depthMap.dispose();
    riseTimeline.kill();
  };

  // -------------------------------------------------
  // Return the prepared Object3D
  // -------------------------------------------------
  return mesh;
}
